    # Keep the largest solid rectangular object, filling isolated holes; background is the most common color.
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    best = None
    # Enumerate bounding boxes and score cells matching one non-background color.
    colors = set(v for row in grid for v in row) - {bg}
    for color in colors:
        pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==color]
        if not pts: continue
        r0,r1=min(r for r,c in pts),max(r for r,c in pts)
        c0,c1=min(c for r,c in pts),max(c for r,c in pts)
        # Connected components of color; the target object is the largest component.
        unseen=set(pts)
        while unseen:
            seed=unseen.pop(); stack=[seed]; comp={seed}
            while stack:
                r,c=stack.pop()
                for p in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):
                    if p in unseen: unseen.remove(p); comp.add(p); stack.append(p)
            rr0=min(r for r,c in comp); rr1=max(r for r,c in comp)
            cc0=min(c for r,c in comp); cc1=max(c for r,c in comp)
            area=(rr1-rr0+1)*(cc1-cc0+1)
            # favor near-filled rectangular components
            score=len(comp) + 0.01*area
            if best is None or score>best[0]: best=(score,color,rr0,rr1,cc0,cc1)
    out=[[bg]*w for _ in range(h)]
    if best:
        _,color,r0,r1,c0,c1=best
        for r in range(r0,r1+1):
            for c in range(c0,c1+1): out[r][c]=color
    return out
